#include "code_scan.h"
#include "checks_sec.h"
int check_format_string(SourceFile*f,Project*p,Issue*out){int cnt=0;int i; for(i=0;i<f->ntokens-3;i++){if(f->tokens[i].type==TK_ID&&strcmp(f->tokens[i].text,"printf")==0){int j=i+2;if(j<f->ntokens&&f->tokens[j].type==TK_ID&&strcmp(f->tokens[j].text,"\"")!=0){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_ERROR;out->cat=CAT_SECURITY;out->code=3001;snprintf(out->msg,sizeof(out->msg),"Format string vulnerability: printf with non-constant format string");snprintf(out->suggestion,sizeof(out->suggestion),"Use printf(\"%%s\", str) instead of printf(str)");}}}if(f->tokens[i].type==TK_ID&&strcmp(f->tokens[i].text,"fprintf")==0){int j=i+3;if(j<f->ntokens&&f->tokens[j].type==TK_ID){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_ERROR;out->cat=CAT_SECURITY;out->code=3001;snprintf(out->msg,sizeof(out->msg),"Format string vulnerability in fprintf");snprintf(out->suggestion,sizeof(out->suggestion),"Use fprintf(stderr, \"%%s\", str) instead");}}}if(f->tokens[i].type==TK_ID&&strcmp(f->tokens[i].text,"sprintf")==0){int j=i+3;if(j<f->ntokens&&f->tokens[j].type==TK_ID){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_WARNING;out->cat=CAT_SECURITY;out->code=3001;snprintf(out->msg,sizeof(out->msg),"Format string in sprintf may be unsafe");}}}return cnt;}}
int check_command_injection(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_ID&&(strcmp(f->tokens[i].text,"system")==0||strcmp(f->tokens[i].text,"popen")==0||strcmp(f->tokens[i].text,"exec")==0||strcmp(f->tokens[i].text,"execl")==0||strcmp(f->tokens[i].text,"execvp")==0||strcmp(f->tokens[i].text,"execve")==0)){int j=i+2;if(j<f->ntokens&&f->tokens[j].type==TK_STRING&&strstr(f->tokens[j].text,"%")!=NULL){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_CRITICAL;out->cat=CAT_SECURITY;out->code=3002;snprintf(out->msg,sizeof(out->msg),"Command injection vulnerability: dynamic command execution");snprintf(out->suggestion,sizeof(out->suggestion),"Use execve() with explicit arguments instead of system()");}}else if(j<f->ntokens&&f->tokens[j].type==TK_ID){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_ERROR;out->cat=CAT_SECURITY;out->code=3002;snprintf(out->msg,sizeof(out->msg),"Command execution with variable argument");snprintf(out->suggestion,sizeof(out->suggestion),"Validate and sanitize all command inputs");}}}}return cnt;}
int check_path_traversal(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_ID&&(strcmp(f->tokens[i].text,"fopen")==0||strcmp(f->tokens[i].text,"open")==0||strcmp(f->tokens[i].text,"access")==0||strcmp(f->tokens[i].text,"stat")==0||strcmp(f->tokens[i].text,"remove")==0||strcmp(f->tokens[i].text,"rename")==0)){int j=i+2;if(j<f->ntokens&&f->tokens[j].type==TK_ID){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_ERROR;out->cat=CAT_SECURITY;out->code=3003;snprintf(out->msg,sizeof(out->msg),"Potential path traversal in file operation");snprintf(out->suggestion,sizeof(out->suggestion),"Validate and sanitize file paths, avoid user-controlled paths");}}}}return cnt;}
int check_hardcoded_creds(SourceFile*f,Project*p,Issue*out){int cnt=0;int i; for(i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_STRING){const char*s=f->tokens[i].text;if(strstr(s,"password")||strstr(s,"passwd")||strstr(s,"secret")||strstr(s,"api_key")||strstr(s,"apikey")||strstr(s,"token")||strstr(s,"auth")){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_CRITICAL;out->cat=CAT_SECURITY;out->code=3004;snprintf(out->msg,sizeof(out->msg),"Hardcoded credential or secret detected");snprintf(out->suggestion,sizeof(out->suggestion),"Store credentials in environment variables or secure config");}}}}if(f->tokens[i].type==TK_ID){const char*s=f->tokens[i].text;if(strstr(s,"password")||strstr(s,"secret")||strstr(s,"api_key")){for(int j=i+1;j<f->ntokens&&j<i+5;j++){if(f->tokens[j].type==TK_EQ&&j+1<f->ntokens&&f->tokens[j+1].type==TK_STRING){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_CRITICAL;out->cat=CAT_SECURITY;out->code=3004;snprintf(out->msg,sizeof(out->msg),"Hardcoded credential assigned to '%s'",s);}}}}}return cnt;}
int check_insecure_temp(SourceFile*f,Project*p,Issue*out){int cnt=0;int i; for(i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_ID&&(strcmp(f->tokens[i].text,"tmpnam")==0||strcmp(f->tokens[i].text,"tempnam")==0||strcmp(f->tokens[i].text,"mktemp")==0)){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_ERROR;out->cat=CAT_SECURITY;out->code=3005;snprintf(out->msg,sizeof(out->msg),"Insecure temporary file creation: %s",f->tokens[i].text);snprintf(out->suggestion,sizeof(out->suggestion),"Use mkstemp() or tmpfile() instead");}}}if(f->tokens[i].type==TK_ID&&strcmp(f->tokens[i].text,"mkstemp")==0){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_INFO;out->cat=CAT_SECURITY;out->code=3005;snprintf(out->msg,sizeof(out->msg),"mkstemp used - ensure umask is restrictive");}}return cnt;}
int check_toctou(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-3;i++){if(f->tokens[i].type==TK_ID&&strcmp(f->tokens[i].text,"access")==0){for(int j=i+1;j<f->ntokens-2&&j<i+20;j++){if(f->tokens[j].type==TK_ID&&(strcmp(f->tokens[j].text,"open")==0||strcmp(f->tokens[j].text,"fopen")==0)){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_WARNING;out->cat=CAT_SECURITY;out->code=3006;snprintf(out->msg,sizeof(out->msg),"TOCTOU race condition: access() followed by open()");snprintf(out->suggestion,sizeof(out->suggestion),"Use open() directly with proper permissions instead of access()+open()");}}}}}return cnt;}
int check_insecure_rand(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_ID&&(strcmp(f->tokens[i].text,"rand")==0||strcmp(f->tokens[i].text,"random")==0||strcmp(f->tokens[i].text,"lrand48")==0||strcmp(f->tokens[i].text,"srand")==0)){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_WARNING;out->cat=CAT_SECURITY;out->code=3007;snprintf(out->msg,sizeof(out->msg),"Insecure random number generator: %s",f->tokens[i].text);snprintf(out->suggestion,sizeof(out->suggestion),"Use arc4random() or getrandom() for security-critical applications");}}}return cnt;}
int check_signal_handler(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_ID&&(strcmp(f->tokens[i].text,"signal")==0||strcmp(f->tokens[i].text,"sigaction")==0)){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_WARNING;out->cat=CAT_SECURITY;out->code=3008;snprintf(out->msg,sizeof(out->msg),"Signal handler registered - ensure only async-signal-safe functions used");snprintf(out->suggestion,sizeof(out->suggestion),"Avoid malloc, printf, and non-reentrant functions in signal handlers");}}}return cnt;}
int check_setuid_usage(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_ID&&(strcmp(f->tokens[i].text,"setuid")==0||strcmp(f->tokens[i].text,"seteuid")==0||strcmp(f->tokens[i].text,"setgid")==0||strcmp(f->tokens[i].text,"setegid")==0)){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_WARNING;out->cat=CAT_SECURITY;out->code=3009;snprintf(out->msg,sizeof(out->msg),"Privilege change function: %s",f->tokens[i].text);snprintf(out->suggestion,sizeof(out->suggestion),"Check return value and drop privileges permanently");}}}return cnt;}
int check_env_var(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_ID&&(strcmp(f->tokens[i].text,"getenv")==0||strcmp(f->tokens[i].text,"secure_getenv")==0)){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_WARNING;out->cat=CAT_SECURITY;out->code=3010;snprintf(out->msg,sizeof(out->msg),"Environment variable read: %s",f->tokens[i].text);snprintf(out->suggestion,sizeof(out->suggestion),"Validate environment variable values before use");}}}return cnt;}
int check_integer_truncation(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-3;i++){if(f->tokens[i].type==TK_LPAREN&&f->tokens[i+1].type==TK_INT&&f->tokens[i+2].type==TK_RPAREN){for(int j=i+3;j<f->ntokens&&j<i+10;j++){if(f->tokens[j].type==TK_NUMBER&&f->tokens[j].val>2147483647LL){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_WARNING;out->cat=CAT_SECURITY;out->code=3011;snprintf(out->msg,sizeof(out->msg),"Integer truncation: casting large value to int");}}}}}return cnt;}
int check_sign_conversion(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-2;i++){if(f->tokens[i].type==TK_LPAREN&&(f->tokens[i+1].type==TK_UNSIGNED||f->tokens[i+1].type==TK_INT)){for(int j=i-3;j>=0&&j>i-10;j--){if(f->tokens[j].type==TK_MINUS){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_WARNING;out->cat=CAT_SECURITY;out->code=3012;snprintf(out->msg,sizeof(out->msg),"Sign conversion: signed to unsigned cast may change value");}}}}}return cnt;}
int check_strcpy_usage(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_ID&&strcmp(f->tokens[i].text,"strcpy")==0){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_ERROR;out->cat=CAT_SECURITY;out->code=3013;snprintf(out->msg,sizeof(out->msg),"Unsafe strcpy() - no bounds checking");snprintf(out->suggestion,sizeof(out->suggestion),"Use strncpy() or strlcpy() with size limit");}}}return cnt;}
int check_strcat_usage(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_ID&&strcmp(f->tokens[i].text,"strcat")==0){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_ERROR;out->cat=CAT_SECURITY;out->code=3014;snprintf(out->msg,sizeof(out->msg),"Unsafe strcat() - no bounds checking");snprintf(out->suggestion,sizeof(out->suggestion),"Use strncat() with remaining buffer size");}}}return cnt;}
int check_gets_usage(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_ID&&strcmp(f->tokens[i].text,"gets")==0){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_CRITICAL;out->cat=CAT_SECURITY;out->code=3015;snprintf(out->msg,sizeof(out->msg),"Dangerous gets() - no bounds checking, buffer overflow risk");snprintf(out->suggestion,sizeof(out->suggestion),"Use fgets() with buffer size limit");}}}return cnt;}
int check_scanf_usage(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-3;i++){if(f->tokens[i].type==TK_ID&&(strcmp(f->tokens[i].text,"scanf")==0||strcmp(f->tokens[i].text,"fscanf")==0||strcmp(f->tokens[i].text,"sscanf")==0)){int j=i+2;if(j<f->ntokens&&f->tokens[j].type==TK_STRING){const char*fmt=f->tokens[j].text;const char*pct=strchr(fmt,'%');while(pct){if(*(pct+1)=='s'||*(pct+1)=='['){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_ERROR;out->cat=CAT_SECURITY;out->code=3016;snprintf(out->msg,sizeof(out->msg),"Unbounded string scan with %%s/%%[]");snprintf(out->suggestion,sizeof(out->suggestion),"Use width specifier: %%<N>s");break;}}pct=strchr(pct+1,'%');}}}}return cnt;}
int check_shell_exec(SourceFile*f,Project*p,Issue*out){int cnt=0;const char*shell_funcs[]={"exec","execl","execle","execlp","execv","execve","execvp","execvpe","system","popen",NULL};for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_ID){for(int s=0;shell_funcs[s];s++){if(strcmp(f->tokens[i].text,shell_funcs[s])==0){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_ERROR;out->cat=CAT_SECURITY;out->code=3017;snprintf(out->msg,sizeof(out->msg),"Shell execution function: %s",shell_funcs[s]);snprintf(out->suggestion,sizeof(out->suggestion),"Avoid shell execution with user input");}}}}}return cnt;}
int check_insecure_crypto(SourceFile*f,Project*p,Issue*out){int cnt=0;const char*weak_crypto[]={"MD5","MD4","SHA1","DES","RC2","RC4","BLOWFISH",NULL};for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_ID){for(int s=0;weak_crypto[s];s++){if(strstr(f->tokens[i].text,weak_crypto[s])!=NULL){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_WARNING;out->cat=CAT_SECURITY;out->code=3018;snprintf(out->msg,sizeof(out->msg),"Weak cryptographic algorithm: %s",weak_crypto[s]);snprintf(out->suggestion,sizeof(out->suggestion),"Use SHA-256 or stronger modern algorithms");}}}}}return cnt;}
int check_constant_seed(SourceFile*f,Project*p,Issue*out){int cnt=0;int i; for(i=0;i<f->ntokens-3;i++){if(f->tokens[i].type==TK_ID&&strcmp(f->tokens[i].text,"srand")==0){int j=i+2;if(j<f->ntokens&&f->tokens[j].type==TK_NUMBER&&f->tokens[j].val<100){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_WARNING;out->cat=CAT_SECURITY;out->code=3019;snprintf(out->msg,sizeof(out->msg),"Constant or small seed for srand()");snprintf(out->suggestion,sizeof(out->suggestion),"Use time(NULL) or getrandom() for seed");}}}}if(f->tokens[i].type==TK_ID&&strcmp(f->tokens[i].text,"srand")==0){int j=i+2;if(j<f->ntokens&&f->tokens[j].type==TK_LPAREN&&j+1<f->ntokens&&f->tokens[j+1].type==TK_RPAREN){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_CRITICAL;out->cat=CAT_SECURITY;out->code=3019;snprintf(out->msg,sizeof(out->msg),"srand() without argument - undefined behavior");}}}return cnt;}
int check_race_condition(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-3;i++){if(f->tokens[i].type==TK_ID&&strcmp(f->tokens[i].text,"thread")==0){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_INFO;out->cat=CAT_CONCURRENCY;out->code=3020;snprintf(out->msg,sizeof(out->msg),"Thread usage detected - check for data races");}}}}
